import * as U from '../ui.js';
import {reset} from '../data.js';
U.mount(()=>{let u=U.db.users[0];return U.heading('Make it yours','Your preferences.','A few small details that make Campus fit your day.')+`<div class="dashboard-grid"><div class="stack">${U.section('Profile & preferences',`<div class="profile" style="border:0;padding:0;margin-bottom:25px"><span class="avatar" style="width:52px;height:52px;font-size:15px">YA</span><div><h3>${U.esc(u.full_name)}</h3><p class="small muted" style="margin-top:6px">Student workspace · Fall 2026</p></div></div><div class="study-day"><p class="small muted">Timezone</p><h3 style="margin-top:8px">${U.esc(u.timezone)}</h3></div><div class="study-day"><p class="small muted">Default currency</p><h3 style="margin-top:8px">${U.esc(u.default_currency_code)}</h3></div>${U.button('Edit profile','users',u.id)}`)}${U.section('Attendance preferences',`<p class="small muted" style="line-height:1.8;margin-bottom:18px">Each course can have a different minimum attendance requirement and rules for late or excused attendance.</p><a class="btn" href="courses.html">Manage course policies →</a>`)}</div><div class="stack">${U.section('About your workspace',`<div class="note">${U.icon('info')}<span>Your workspace is saved separately under your signed-in account on this Campus installation. Courses, budgets, tasks, notes, and appointments are private to that account.</span></div><p class="small muted" style="margin:18px 0;line-height:1.8">Changing the default currency does not convert historical transactions. Each monthly budget keeps its own currency.</p><a href="setup.html" class="text-link">Open getting started →</a>`)}${U.section('Workspace controls',`<p class="small muted" style="line-height:1.8;margin-bottom:18px">Clear only your own courses, tasks, budget, notes, and appointments. Your account and profile stay.</p><button class="btn danger" id="reset-demo">Clear my workspace</button><hr style="border:0;border-top:1px solid var(--line);margin:22px 0"><a class="btn" href="login.html">${U.icon('logout')} Go to Login</a>`)}</div></div>`});
document.addEventListener('click',e=>{if(e.target.id==='reset-demo'){let d=document.querySelector('#editor');d.innerHTML=`<div class="dialog-head"><h2>Clear your workspace?</h2><button class="icon-btn" id="close-reset" aria-label="Close">${U.icon('close')}</button></div><div style="padding:25px"><p class="muted" style="line-height:1.8">This permanently clears the data in your own workspace. Other accounts are not affected.</p><div class="actions" style="margin-top:22px"><button class="btn" id="keep-demo">Keep my changes</button><button class="btn primary" id="confirm-reset">Clear workspace</button></div></div>`;d.showModal();d.querySelector('#close-reset').onclick=d.querySelector('#keep-demo').onclick=()=>d.close();d.querySelector('#confirm-reset').onclick=()=>{reset();d.close();U.toast('Your workspace is now empty.')}}});
